1	export type Cell = [number, number];
2	
3	const key = (x: number, y: number): string => `${x},${y}`;
4	
5	const neighborsOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	export function nextGeneration(liveCells: Cell[]): Cell[] {
17	  const living = new Set(liveCells.map(([x, y]) => key(x, y)));
18	
19	  const liveNeighborCount = (cell: Cell): number =>
20	    neighborsOf(cell).filter(([x, y]) => living.has(key(x, y))).length;
21	
22	  const candidates = new Map<string, Cell>();
23	  for (const cell of liveCells) {
24	    candidates.set(key(cell[0], cell[1]), cell);
25	    for (const neighbor of neighborsOf(cell)) {
26	      candidates.set(key(neighbor[0], neighbor[1]), neighbor);
27	    }
28	  }
29	
30	  const survivors: Cell[] = [];
31	  for (const [cellKey, cell] of candidates) {
32	    const count = liveNeighborCount(cell);
33	    const isAlive = living.has(cellKey);
34	    if (count === 3 || (isAlive && count === 2)) {
35	      survivors.push(cell);
36	    }
37	  }
38	
39	  return survivors;
40	}
