const living = new Set(liveCells.map(keyOf));

const liveNeighborCount = (cell: Cell): number =>
  neighborsOf(cell).filter((neighbor) => living.has(keyOf(neighbor))).length;

const candidates = new Map<string, Cell>();
for (const cell of liveCells) {
  for (const candidate of [cell, ...neighborsOf(cell)]) {
    candidates.set(keyOf(candidate), candidate);
  }
}

const nextLiveCells: Cell[] = [];
for (const [cellKey, cell] of candidates) {
  const count = liveNeighborCount(cell);
  const isAlive = living.has(cellKey);
  if (count === 3 || (isAlive && count === 2)) {
    nextLiveCells.push(cell);
  }
}

return nextLiveCells;
